// 完全背包 DP：dp[a] = 湊出金額 a 的最少硬幣數
// 時間複雜度: O(amount × n)，空間複雜度: O(amount)
int coinChange(int* coins, int coinsSize, int amount) {
    int* dp = malloc(sizeof(int) * (amount + 1));
    dp[0] = 0;
    for (int a = 1; a <= amount; a++) {
        dp[a] = INT_MAX;
        for (int i = 0; i < coinsSize; i++) {
            int c = coins[i];
            if (c <= a && dp[a - c] != INT_MAX && dp[a - c] + 1 < dp[a]) {
                dp[a] = dp[a - c] + 1;
            }
        }
    }
    int ans = dp[amount] == INT_MAX ? -1 : dp[amount];
    free(dp);
    return ans;
}

